import React, { useState, useEffect } from 'react';


// ── Citation copy button ──────────────────────────────────────────────────────
function CitationCopyButton() {
  const [copied, setCopied] = useState(false);
  const year = new Date().getFullYear();
  const text = `Shelvy, S., Archana, S., Ramesh, R., Sathee, L., & Viswanathan, C. (${year}). PlantaCRISPAI: An AI-powered universal CRISPR genotyping platform for Sanger sequencing data from genome-edited plants [Software]. Division of Plant Physiology, ICAR-Indian Agricultural Research Institute. https://plantacrispai.netlify.app`;
  return (
    <button
      onClick={() => { navigator.clipboard.writeText(text).then(() => { setCopied(true); setTimeout(() => setCopied(false), 2000); }); }}
      style={{
        position: 'absolute', top: 10, right: 10,
        background: copied ? 'rgba(0,212,170,0.2)' : 'rgba(255,255,255,0.06)',
        border: `1px solid ${copied ? 'rgba(0,212,170,0.5)' : 'rgba(255,255,255,0.1)'}`,
        color: copied ? '#00d4aa' : '#8899bb',
        borderRadius: 8, padding: '5px 12px', cursor: 'pointer', fontSize: 11,
        fontFamily: "'Inter', sans-serif", transition: 'all 0.2s',
      }}>
      {copied ? '✅ Copied!' : '📋 Copy'}
    </button>
  );
}

// ── BibTeX block ──────────────────────────────────────────────────────────────
function BibTeXBlock() {
  const [open, setOpen] = useState(false);
  const [copied, setCopied] = useState(false);
  const year = new Date().getFullYear();
  const bibtex = `@software{shelvy${year}plantacrispai,
  author    = {Shelvy, S. and Archana, S. and Ramesh, R. and Sathee, L. and Viswanathan, C.},
  title     = {{PlantaCRISPAI}: An {AI}-powered universal {CRISPR} genotyping platform for {Sanger} sequencing data from genome-edited plants},
  year      = {${year}},
  publisher = {Division of Plant Physiology, ICAR-Indian Agricultural Research Institute},
  url       = {https://plantacrispai.netlify.app}
}`;
  return (
    <div style={{ marginTop: 14 }}>
      <button onClick={() => setOpen(o => !o)} style={{
        background: 'transparent', border: '1px solid rgba(255,255,255,0.1)',
        color: '#8899bb', borderRadius: 8, padding: '5px 14px', cursor: 'pointer',
        fontSize: 11, fontFamily: "'Inter', sans-serif", transition: 'all 0.2s',
      }}>
        {open ? '▲ Hide BibTeX' : '▼ Show BibTeX'}
      </button>
      {open && (
        <div style={{ position: 'relative', marginTop: 10 }}>
          <pre style={{
            background: 'rgba(0,0,0,0.3)', border: '1px solid rgba(255,255,255,0.08)',
            borderRadius: 10, padding: '14px 16px',
            fontFamily: "'Courier New', monospace", fontSize: 11,
            color: '#a8c8f0', lineHeight: 1.7, overflowX: 'auto',
            whiteSpace: 'pre', margin: 0,
          }}>{bibtex}</pre>
          <button onClick={() => { navigator.clipboard.writeText(bibtex).then(() => { setCopied(true); setTimeout(() => setCopied(false), 2000); }); }}
            style={{
              position: 'absolute', top: 8, right: 8,
              background: copied ? 'rgba(0,212,170,0.2)' : 'rgba(255,255,255,0.06)',
              border: `1px solid ${copied ? 'rgba(0,212,170,0.5)' : 'rgba(255,255,255,0.1)'}`,
              color: copied ? '#00d4aa' : '#8899bb',
              borderRadius: 7, padding: '4px 10px', cursor: 'pointer', fontSize: 10,
              fontFamily: "'Inter', sans-serif", transition: 'all 0.2s',
            }}>
            {copied ? '✅ Copied!' : '📋 Copy'}
          </button>
        </div>
      )}
    </div>
  );
}

